import os
import shutil
import uuid

# Constants
BACKUP_DIR = '/tmp/backup'

def get_unique_backup_dir():
    while True:
        candidate = os.path.join(BACKUP_DIR, f"backup-{uuid.uuid4().hex}")
        if not os.path.exists(candidate):
            return candidate

def _is_within(path, parent):
    try:
        path = os.path.abspath(path)
        parent = os.path.abspath(parent)
        return os.path.commonpath([path, parent]) == parent
    except Exception:
        return False

def _add_error(errors, message, exc=None):
    if exc is None:
        errors.append(message)
    else:
        errors.append(f"{message}: {exc}")

def _copy_tree(src, dst, errors):
    try:
        os.makedirs(dst, exist_ok=True)
    except Exception as exc:
        _add_error(errors, f"Failed to create backup directory '{dst}'", exc)
        return False

    try:
        entries = list(os.scandir(src))
    except Exception as exc:
        _add_error(errors, f"Failed to list source directory '{src}'", exc)
        return False

    fatal_error = False

    for entry in entries:
        src_path = entry.path

        # Prevent the backup from recursively copying itself when the backup
        # directory lives inside the source tree.
        if _is_within(src_path, dst):
            continue

        dst_path = os.path.join(dst, entry.name)

        try:
            if entry.is_symlink():
                os.symlink(os.readlink(src_path), dst_path)
            elif entry.is_dir(follow_symlinks=False):
                if not _copy_tree(src_path, dst_path, errors):
                    fatal_error = True
                try:
                    shutil.copystat(src_path, dst_path, follow_symlinks=False)
                except Exception as exc:
                    _add_error(errors, f"Failed to preserve directory metadata for '{src_path}'", exc)
            else:
                shutil.copy2(src_path, dst_path, follow_symlinks=False)
        except Exception as exc:
            fatal_error = True
            _add_error(errors, f"Failed to copy '{src_path}' to '{dst_path}'", exc)

    try:
        shutil.copystat(src, dst, follow_symlinks=False)
    except Exception as exc:
        _add_error(errors, f"Failed to preserve metadata for '{src}'", exc)

    return not fatal_error

def _remove_path(path, errors, preserve=None):
    if preserve is not None and _is_within(path, preserve):
        return

    try:
        if os.path.islink(path) or os.path.isfile(path):
            os.unlink(path)
            return

        if os.path.isdir(path):
            try:
                entries = list(os.scandir(path))
            except Exception as exc:
                _add_error(errors, f"Failed to list directory '{path}' for cleanup", exc)
                return

            for entry in entries:
                _remove_path(entry.path, errors, preserve=preserve)

            try:
                os.rmdir(path)
            except OSError:
                pass
            return

        os.unlink(path)
    except FileNotFoundError:
        return
    except Exception as exc:
        _add_error(errors, f"Failed to remove '{path}'", exc)

def task_func(directory):
    errors = []
    backup_dir = get_unique_backup_dir()

    try:
        src = os.fspath(directory)
    except Exception as exc:
        _add_error(errors, "Invalid directory path", exc)
        return backup_dir, errors

    src = os.path.abspath(src)

    if not os.path.exists(src):
        errors.append(f"Source directory does not exist: '{src}'")
        return backup_dir, errors

    if not os.path.isdir(src):
        errors.append(f"Source path is not a directory: '{src}'")
        return backup_dir, errors

    try:
        os.makedirs(BACKUP_DIR, exist_ok=True)
    except Exception as exc:
        _add_error(errors, f"Failed to create backup root '{BACKUP_DIR}'", exc)
        return backup_dir, errors

    backup_ok = _copy_tree(src, backup_dir, errors)

    if backup_ok:
        try:
            entries = list(os.scandir(src))
        except Exception as exc:
            _add_error(errors, f"Failed to list source directory '{src}' for cleanup", exc)
            return backup_dir, errors

        for entry in entries:
            _remove_path(entry.path, errors, preserve=backup_dir)

    return backup_dir, errors
